"""specs_s200021.py - Sonnet-w2 family A (generated by mkfamA.py). Slot 0x34 stub, 0x4690b0 hook and the assert hook at 0x7003b0 record the SEH chain
(seh_record) and the object's vtable word; fake outer SEH records 0-2; fs:[0] compared after return. flags cover all of bits 0..2 and random values."""
from pilot import S
from recruits_util import rnd, obj, clear_hooks, hook_rec, pystub, seh_record, seh_chain


def _side(c, o):
    sr = seh_record(c, 2)

    def side(emu, k):
        emu.calllog.append(('vt', emu.r32(o)))
        sr(emu, k)
    return side


def _gen(c):
    clear_hooks(c)
    seh_chain(c, c.rng.choice([0, 1, 2]))
    r = c.rng
    o = rnd(c, 0x100)
    hook_rec(c, 0x4690b0, 2, ret=r.getrandbits(32), pop=0, side=_side(c, o))
    eng = rnd(c, 0x1b00)
    c.emu.w32(0x70039c, eng)
    t = obj(c, 0x40, {0x34: pystub(c, 1, ret=r.getrandbits(32), this=True, side=_side(c, o))}, nslots=0x14)
    c.emu.w32(eng + 0x9b, t)
    side = _side(c, o)
    n = [0]

    def ah(e2, res_):
        e2.calllog.append(('assert',))
        side(e2, n[0])
        n[0] += 1
        e2.ret(eax=r.getrandbits(32))
    c.emu.w32(0x7003b0, c.emu.stub_fn('assert hook', ah))
    return [o, r.choice([0, 1, 2, 3, 4, 5, 6, 7, 0x100, 0xffffffff, r.getrandbits(32)])]


S(0x5bc2f0, 'GUESS famA 0x5bc2f0', 'thiscall', None, ret='eax', gen=_gen, note='batch200021')
